						if (gk > 0.0) c = mix(c, mix(mix(vec3(0.16, 0.3, 0.07), vec3(0.22, 0.36, 0.1), n2), vec3(0.05, 0.1, 0.04), smoothstep(0.5, 0.62, n1 + n3 * 0.1) * 0.85), gk);
